-- REQUIRED IN SUPABASE SQL EDITOR: webhook delivery center foundation.
CREATE TABLE IF NOT EXISTS public.webhook_endpoints(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,name text NOT NULL,url text NOT NULL,secret_ciphertext text NOT NULL,subscribed_events text[] NOT NULL DEFAULT '{}',is_active boolean NOT NULL DEFAULT false,failure_count integer NOT NULL DEFAULT 0,last_success_at timestamptz,last_failure_at timestamptz,disabled_at timestamptz,created_by uuid NOT NULL REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.webhook_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,event_type text NOT NULL,schema_version text NOT NULL DEFAULT '1.0',subject_id uuid,payload jsonb NOT NULL,idempotency_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,idempotency_key));
CREATE TABLE IF NOT EXISTS public.webhook_deliveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,endpoint_id uuid NOT NULL REFERENCES public.webhook_endpoints(id) ON DELETE CASCADE,event_id uuid NOT NULL REFERENCES public.webhook_events(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'pending',attempt_count integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),last_error text,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(endpoint_id,event_id));
CREATE TABLE IF NOT EXISTS public.webhook_delivery_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,delivery_id uuid NOT NULL REFERENCES public.webhook_deliveries(id) ON DELETE CASCADE,attempt_number integer NOT NULL,response_code integer,response_excerpt text,error text,duration_ms integer,attempted_at timestamptz NOT NULL DEFAULT now(),UNIQUE(delivery_id,attempt_number));
CREATE INDEX IF NOT EXISTS webhook_endpoints_org_idx ON public.webhook_endpoints(org_id,is_active); CREATE INDEX IF NOT EXISTS webhook_deliveries_retry_idx ON public.webhook_deliveries(status,next_attempt_at); CREATE INDEX IF NOT EXISTS webhook_attempts_delivery_idx ON public.webhook_delivery_attempts(delivery_id,attempted_at DESC);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['webhook_endpoints','webhook_events','webhook_deliveries','webhook_delivery_attempts'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I',t||'_select',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.organization_members m WHERE m.org_id=%I.org_id AND m.user_id=auth.uid()))',t||'_select',t,t); EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I',t||'_admin',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.organization_members m WHERE m.org_id=%I.org_id AND m.user_id=auth.uid() AND m.role=''admin'')) WITH CHECK(EXISTS(SELECT 1 FROM public.organization_members m WHERE m.org_id=%I.org_id AND m.user_id=auth.uid() AND m.role=''admin''))',t||'_admin',t,t,t); END LOOP; END $$;
